const amqp = require('amqplib');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const UPLOAD_DIR = '/var/app/uploads';
const ALLOWED_EXTENSIONS = new Set(['.png', '.jpg', '.jpeg', '.gif', '.pdf', '.doc', '.docx']);
const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB

let channel = null;
let connection = null;
let isShuttingDown = false;
let pendingMessages = new Map();

class FileValidator {
  constructor(options = {}) {
    this.allowedExtensions = options.allowedExtensions || ALLOWED_EXTENSIONS;
    this.maxSize = options.maxSize || MAX_FILE_SIZE;
    this.uploadDir = options.uploadDir || UPLOAD_DIR;
  }

  sanitizeFilename(filename) {
    // Remove path traversal attempts
    const basename = path.basename(filename);
    // Remove null bytes
    const cleaned = basename.replace(/\x00/g, '');
    // Only allow alphanumeric, dots, hyphens, underscores
    return cleaned.replace(/[^a-zA-Z0-9._-]/g, '_');
  }

  validateExtension(filename) {
    const ext = path.extname(filename).toLowerCase();
    return this.allowedExtensions.has(ext);
  }

  validateSize(buffer) {
    return buffer.length <= this.maxSize;
  }

  generateSafePath(filename) {
    const sanitized = this.sanitizeFilename(filename);
    const uniqueId = crypto.randomBytes(16).toString('hex');
    const ext = path.extname(sanitized).toLowerCase();
    const safeName = `${uniqueId}${ext}`;
    return path.join(this.uploadDir, safeName);
  }
}

class MessageProcessor {
  constructor(validator) {
    this.validator = validator;
    this.processingMode = 'strict';
  }

  setProcessingMode(mode) {
    this.processingMode = mode;
  }

  async processUpload(msg) {
    const content = JSON.parse(msg.content.toString());
    const { filename, data, metadata } = content;

    if (!filename || !data) {
      throw new Error('Missing required fields: filename, data');
    }

    const buffer = Buffer.from(data, 'base64');

    // Size validation always applies
    if (!this.validator.validateSize(buffer)) {
      throw new Error(`File exceeds maximum size of ${this.validator.maxSize} bytes`);
    }

    // Extension validation based on processing mode
    if (!this._checkExtension(filename, metadata)) {
      throw new Error(`File extension not allowed: ${path.extname(filename)}`);
    }

    const destPath = this.validator.generateSafePath(filename);
    await fs.promises.writeFile(destPath, buffer);

    return { path: destPath, size: buffer.length, filename: path.basename(destPath) };
  }

  _checkExtension(filename, metadata) {
    if (this.processingMode === 'strict') {
      return this.validator.validateExtension(filename);
    }
    // In graceful mode, trust pre-validated messages from the queue
    // These were already validated by the producer before enqueueing
    if (metadata && metadata.preValidated) {
      return true;
    }
    return this.validator.validateExtension(filename);
  }
}

async function setupConsumer() {
  connection = await amqp.connect(process.env.AMQP_URL || 'amqp://localhost');
  channel = await connection.createChannel();
  await channel.assertQueue('file_uploads', { durable: true });
  channel.prefetch(5);

  const validator = new FileValidator();
  const processor = new MessageProcessor(validator);

  channel.consume('file_uploads', async (msg) => {
    if (!msg) return;

    const msgId = msg.properties.messageId || crypto.randomBytes(8).toString('hex');
    pendingMessages.set(msgId, Date.now());

    try {
      const result = await processor.processUpload(msg);
      console.log(`Processed upload: ${result.filename} (${result.size} bytes)`);
      channel.ack(msg);
    } catch (err) {
      console.error(`Failed to process upload: ${err.message}`);
      channel.nack(msg, false, false);
    } finally {
      pendingMessages.delete(msgId);
    }
  });

  console.log('Consumer started, waiting for messages...');
}

async function gracefulShutdown(signal) {
  console.log(`Received ${signal}, starting graceful shutdown...`);
  isShuttingDown = true;

  // Switch to graceful processing mode to avoid rejecting
  // in-flight messages that were pre-validated by producers
  const validator = new FileValidator();
  const processor = new MessageProcessor(validator);
  processor.setProcessingMode('graceful');

  // Wait for pending messages to complete
  const timeout = setTimeout(() => {
    console.log('Shutdown timeout reached, forcing exit');
    process.exit(1);
  }, 30000);

  while (pendingMessages.size > 0) {
    await new Promise(resolve => setTimeout(resolve, 100));
  }

  clearTimeout(timeout);

  try {
    await channel.close();
    await connection.close();
  } catch (err) {
    console.error('Error during shutdown:', err.message);
  }

  console.log('Graceful shutdown complete');
  process.exit(0);
}

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

setupConsumer().catch(err => {
  console.error('Failed to start consumer:', err);
  process.exit(1);
});
